# Generated by sync_menu_ui; edit canonical sources.
"""The camera profile window at work (decisions of 2026-10-12): the floppy hides the menu and opens the window alone in
the screen's corner on a new profile, every change goes to the shared profiles' draft and shows in game at once,
CANCEL puts the camera back, SAVE keeps the profile and switches it on; both bring the menu back. While the window is
closed, the PROFILES page has its turn (panel_profile_list.py); its EDIT opens the window on a saved profile.

The draft lives in the camera runtime, not here: Escape closes everything without losing it, and the menu opens on the
window again, whichever camera mod's menu it is. The menu's form makes one of these at each opening and asks it first
at each turn (panel_form_lifecycle.poll_popup).
"""

from . import camera, panel_profile_grey as grey, panel_profile_paint, panel_profile_text as words
from . import panel_profile_window as view, panel_widgets as w
from .panel_profile_list import ProfileList
from .camera_control_form import Form as CommandForm

try:
    from .apex_camera_runtime.profile_entry import MAX_NAME
    from .apex_camera_runtime.profile_store import MAX_PROFILES
except ModuleNotFoundError as error:
    if error.name != f"{__package__}.apex_camera_runtime":
        raise
    from apex_camera_runtime.profile_entry import MAX_NAME
    from apex_camera_runtime.profile_store import MAX_PROFILES

# The keys a capture ends on without choosing: Escape, and a second click on CHANGE (camera_control_form.py).
CANCELLING = ("Escape", "LeftMouseButton")


class ProfileForm:
    def __init__(self, form):
        self.form = form
        self.sources = view.sources(form.model)
        self.fields = {field: view.slider_field(field, option) for field, (option, _group) in self.sources.items()}
        self.open = self.floppy = False
        # A refusal of the window's (panel_profile_text.py), shown until the next change of key or save.
        self.notice = None
        self.painted = self.greyed = None
        widgets = form.resolve()
        self.page = ProfileList(form, widgets)
        profiles = self.profiles()
        if profiles is not None and profiles.draft is not None:
            # Opened while a profile is being tuned: the window shows at once, the menu never shows in between.
            self._show(widgets, profiles.draft)
        else:
            # The PROFILES page and its button as the menu first shows, not a turn later.
            self.page.poll(widgets, profiles)

    def profiles(self):
        """The shared profiles this menu may change, or None: the floppy then stays hidden."""
        if self.form.model.camera_elsewhere:
            return None
        profiles = camera.profiles()
        return profiles if profiles is not None and profiles.available() else None

    def poll(self, widgets):
        """Each turn of the window; True while the profile window is open, as it alone takes the clicks then."""
        profiles = self.profiles()
        self._floppy(widgets, profiles is not None)
        draft = None if profiles is None else profiles.draft
        if draft is None and profiles is not None and self.form.take(widgets["profile:floppy"]):
            draft = self._open_new(widgets, profiles)
        if draft is None:
            self._close(widgets)
            draft = self.page.poll(widgets, profiles)
            if draft is None:
                return False
        if not self.open:
            self._show(widgets, draft)
        view.hold_focus(widgets)
        self._read_name(widgets, profiles)
        if self.form.take(widgets["profile:cancel"]):
            profiles.cancel()
            self._close(widgets)
            return True
        if self.form.take(widgets["profile:save"]):
            self._save(widgets, profiles)
        else:
            self._read_settings(widgets, profiles)
            self._read_keys(widgets, profiles)
        # Still open after a refused save: its reason shows at once.
        if self.open:
            self._paint(widgets, profiles.draft)
        return True

    def held(self):
        """The profile switched on, whose settings the pages grey; None while none is or the profiles are hidden."""
        return grey.held(self.profiles())

    def holds(self, group):
        """Whether a framing card's setting is a profile's while one is on (panel_framing_form.Form.enabled)."""
        return group in view.FRAMING.values() and self.held() is not None

    def grey(self, widgets):
        """After the menu's own greying of its rows (panel_form.refresh_dependency)."""
        profile = self.held()
        grey.rows(widgets, profile)
        state = (profile, self.form.model.language)
        if state != self.greyed:
            self.greyed = state
            grey.notices(widgets, profile, self.form.model.language)

    def selecting(self):
        """A key capture is on: Escape then ends it, and never the menu (control_escape.py)."""
        if not self.open:
            return False
        widgets = self.form.resolve()
        return any(widgets[f"command:profile:{device}"].GetIsSelectingKey() for device in view.DEVICES)

    def _floppy(self, widgets, shown):
        if shown != self.floppy:
            self.floppy = shown
            visibility = "Visible" if shown else "Collapsed"
            widgets["profile:floppy_body"].SetVisibility(w.enum("ESlateVisibility", visibility))

    def _open_new(self, widgets, profiles):
        if len(profiles.ready().profiles) >= MAX_PROFILES:
            # Rather than a window whose SAVE could only refuse and whose CANCEL would lose the tuning.
            self.form.report(widgets, "profiles_full_floppy")
            return None
        # What the page had pending is saved first, as before any change of page (panel_options_tabs.show).
        if not self.form.flush(widgets):
            self.form.report(widgets, "failed")
            return None
        word = words.text("profile_word", self.form.model.language)
        profiles.open_new(profiles.free_name(word), camera.ADAPTER, camera.shown_fov())
        return profiles.draft

    def _show(self, widgets, draft):
        self.open, self.notice, self.painted = True, None, None
        for field in view.FIELDS:
            widgets[f"setting:profile:{field}"].SetValue(float(getattr(draft.values, field)))
        widgets["profile:name"].SetText(draft.name)
        view.show(widgets)

    def _close(self, widgets):
        if self.open:
            self.open = False
            view.hide(widgets)

    def _read_name(self, widgets, profiles):
        box = widgets["profile:name"]
        name = str(box.GetText())
        if len(name) > MAX_NAME:
            name = name[:MAX_NAME]
            box.SetText(name)
        if name != profiles.draft.name:
            profiles.rename(name)

    def _read_settings(self, widgets, profiles):
        for field, (_option, group) in self.sources.items():
            slider = widgets[f"setting:profile:{field}"]
            for index, (_label, number) in enumerate(() if group is None else group.presets):
                if self.form.take(widgets[f"profile:{field}:preset:{index}"]):
                    slider.SetValue(float(number))
            current = getattr(profiles.draft.values, field)
            raw = slider.GetValue()
            step = self.fields[field].step
            if abs(raw - current) < max(1e-6, step * 0.01):
                continue
            try:
                profiles.change(field, round(raw) if self.fields[field].is_integer else round(raw, 2))
            except (TypeError, ValueError, OverflowError):
                slider.SetValue(float(current))

    def _read_keys(self, widgets, profiles):
        """As the COMMANDS page reads its keys (camera_control_form.py): one capture at a time."""
        selectors = {device: widgets[f"command:profile:{device}"] for device in view.DEVICES}
        busy = [device for device, selector in selectors.items() if selector.GetIsSelectingKey()]
        for device, selector in selectors.items():
            selector.SetIsEnabled(not busy or device == busy[0])
        if busy:
            return
        for device, selector in selectors.items():
            if self.form.take(widgets[f"clear:profile:{device}"]):
                self._set_key(profiles, device, None)
                continue
            key = str(selector.SelectedKey.Key.KeyName)
            if key in ("", "None"):
                continue
            CommandForm.clear_selector(selector)
            if key not in CANCELLING:
                self._set_key(profiles, device, key)

    def _set_key(self, profiles, device, key):
        draft = profiles.draft
        chosen = {"keyboard": draft.keyboard, "controller": draft.controller, device: key}
        taken = {option.value for option in self.form.model.command_options.values()}
        if self.form.open_key is not None:
            taken.add(self.form.open_key.key())  # the key that opens the window (open_key.py)
        if key is not None and key in taken:
            self.notice = "key_command"
            return
        try:
            profiles.set_keys(chosen["keyboard"], chosen["controller"])
            self.notice = None
        except ValueError as error:
            self.notice = self._reason(error)

    def _save(self, widgets, profiles):
        try:
            profiles.save()
        except OSError:
            self.notice = "save_failed"
            return
        except ValueError as error:
            self.notice = self._reason(error)
            return
        self._close(widgets)
        self.form.report(widgets, "saved")

    @staticmethod
    def _reason(error):
        # Caught by its reason, not its class: the shared runtime may be another camera mod's copy (shared.py).
        reason = getattr(error, "reason", None)
        return reason if reason in words.REFUSALS else "profile_refused"

    def _paint(self, widgets, draft):
        model = self.form.model
        state = (draft.values, draft.keyboard, draft.controller, draft.editing, self.notice, model.language,
                 model.controller_icons)
        if state != self.painted:
            self.painted = state
            panel_profile_paint.paint(widgets, self, draft, self.notice)
